1	#!/usr/bin/env bun
2	/**
3	 * files_guard.ts — counts a search made through the `files` server, and refuses one
4	 * once too many have gone by with nothing opened.
5	 *
6	 * ## Why this exists
7	 *
8	 * `shell_guard` has always counted searches, but only the ones made by running `grep`
9	 * in a shell. Giving the agents a real `grep` tool would otherwise have opened a path
10	 * around the counter: the same act, through a better door, uncounted. The rule would
11	 * then fire only on the agents that have a shell, and only for the searches they chose
12	 * to make the slow way.
13	 *
14	 * The rule itself is unchanged and lives in `domain/work/search-streak.ts`, which holds the
15	 * limit and the wording. This is the door, not the rule.
16	 *
17	 * ## What counts
18	 *
19	 * `grep`, `glob` and `list` answer *where* something is. `read` answers what it says,
20	 * and clears the counter through `note_file_opened`. That division is the whole point:
21	 * a run that enumerates for ever without opening anything is the shape being caught,
22	 * and it does not matter which tool it enumerates with.
23	 *
24	 * ## Fail-closed, and what that means here
25	 *
26	 * The core treats a non-zero exit or unparseable output from a `before_tool` hook as a
27	 * refusal. So every path that cannot decide answers `allow: true` explicitly rather
28	 * than falling through: a counter that cannot be read must leave the rule off, not
29	 * refuse every call the agent makes. `readStreak` is written to the same rule.
30	 */
31	import { nextStreak, refusalReason } from "../../../domain/work/search-streak.ts";
32	import { readStreak, streakFile, writeStreak } from "../lib/search-streak-file.ts";
33	
34	/**
35	 * The tools here that answer "where".
36	 *
37	 * Named without a prefix because this server sets `unprefixed: true`, and matched
38	 * after stripping one anyway: the same file is declared as `files` and as
39	 * `files_readonly`, and a copy of this list keyed to one spelling would stop applying
40	 * to the other the day either is renamed.
41	 */
42	const SEARCHES = new Set(["grep", "glob", "list"]);
43	
44	function allow(): void {
45	  console.log(JSON.stringify({ allow: true }));
46	}
47	
48	async function main(): Promise<void> {
49	  let tool = "";
50	  try {
51	    const raw = await new Response(Bun.stdin.stream()).text();
52	    tool = String((JSON.parse(raw) as { tool?: unknown }).tool ?? "");
53	  } catch {
54	    // Unreadable input says nothing about what was called. Refusing here would refuse
55	    // every call rather than the one that could not be read.
56	    allow();
57	    return;
58	  }
59	
60	  if (!SEARCHES.has(tool.trim().replace(/^.*__/, ""))) {
61	    allow();
62	    return;
63	  }
64	
65	  // Advance and record before deciding, matching `shell_guard`: a refused search still
66	  // happened as far as the counter is concerned, and a counter that stood still while
67	  // the agent kept asking would never reach the limit at all.
68	  const file = streakFile();
69	  const streak = nextStreak(readStreak(file), "search");
70	  writeStreak(file, streak);
71	
72	  const refusal = refusalReason(streak);
73	  if (refusal) {
74	    console.log(JSON.stringify({ allow: false, reason: refusal }));
75	    return;
76	  }
77	  allow();
78	}
79	
80	if (import.meta.main) await main();

