1	#!/usr/bin/env bun
2	/**
3	 * workspace_guard.ts — tells the agent when its scratch workspace has grown past
4	 * what will be carried into the next run, while it can still do something about it.
5	 *
6	 * Invoked as an `after_tool` hook declared once in `tools.watch`, so it runs after
7	 * every call to every server. See `domain/work/workspace-size.ts` for why it is every server
8	 * and why the check is here rather than where the workspace is saved.
9	 *
10	 * ## What it answers
11	 *
12	 * `{"notice": "..."}` on stdout, which Atoma appends to the result the agent is already
13	 * reading. Anything else — no output, a crash, a timeout — adds nothing and the call it
14	 * followed is unaffected. That is the contract this side is written to: an after-hook
15	 * reports on work that has already happened, so this file never fails a tool call, and
16	 * every error path below ends in silence rather than in an exception.
17	 *
18	 * ## Why it walks the tree on every call
19	 *
20	 * The measured workspace is five files. Walking it costs microseconds, and the walk
21	 * stops early once it has seen enough to know the answer, so the pathological case —
22	 * somebody copied `node_modules` in — is the cheapest one to detect rather than the most
23	 * expensive. What it must not do is cache: the file that matters is the one written by
24	 * the call that just finished.
25	 */
26	import { readdirSync, statSync } from "node:fs";
27	import { join } from "node:path";
28	import { WORKSPACE_PATH } from "../../../domain/work/workspace.ts";
29	import { MAX_FILES, overLimitNotice, type WorkspaceUsage } from "../../../domain/work/workspace-size.ts";
30	
31	/**
32	 * Stop walking once this many files have been seen.
33	 *
34	 * Past `MAX_FILES` the answer cannot change: the count alone already trips the limit,
35	 * and the notice names the largest files it found rather than claiming to have found
36	 * the largest that exist. Bounded work on a directory whose size is the problem.
37	 */
38	const WALK_CEILING = MAX_FILES + 1;
39	
40	/** How many of the largest files to keep while walking. The notice names three. */
41	const KEEP_LARGEST = 5;
42	
43	function measure(root: string): WorkspaceUsage {
44	  const usage: WorkspaceUsage = { bytes: 0, files: 0, largest: [] };
45	  const stack = [root];
46	
47	  while (stack.length > 0 && usage.files < WALK_CEILING) {
48	    const dir = stack.pop()!;
49	    let entries;
50	    try {
51	      entries = readdirSync(dir, { withFileTypes: true });
52	    } catch {
53	      // A directory that cannot be read is not a reason to say anything: the
54	      // workspace may simply not exist yet, which is the common case.
55	      continue;
56	    }
57	    for (const entry of entries) {
58	      if (usage.files >= WALK_CEILING) break;
59	      const path = join(dir, entry.name);
60	      if (entry.isDirectory()) {
61	        stack.push(path);
62	        continue;
63	      }
64	      // Symlinks are counted as the link, not as what they point at: following them
65	      // would let one into a size that is not in the workspace at all, and would
66	      // loop on a cycle.
67	      if (!entry.isFile()) continue;
68	      let size;
69	      try {
70	        size = statSync(path).size;
71	      } catch {
72	        continue;
73	      }
74	      usage.files += 1;
75	      usage.bytes += size;
76	      usage.largest.push({ path, bytes: size });
77	      if (usage.largest.length > KEEP_LARGEST * 4) {
78	        usage.largest.sort((a, b) => b.bytes - a.bytes);
79	        usage.largest.length = KEEP_LARGEST;
80	      }
81	    }
82	  }
83	
84	  usage.largest.sort((a, b) => b.bytes - a.bytes);
85	  usage.largest.length = Math.min(usage.largest.length, KEEP_LARGEST);
86	  return usage;
87	}
88	
89	async function main(): Promise<void> {
90	  // The payload is read and discarded. Nothing here depends on which tool ran: the
91	  // question is about the directory's state, and the answer is the same whoever asked.
92	  // It is still read, because leaving stdin unread closes the pipe under the writer.
93	  try {
94	    await new Response(Bun.stdin.stream()).text();
95	  } catch {
96	    // Nothing to do with it either way.
97	  }
98	
99	  try {
100	    const notice = overLimitNotice(measure(WORKSPACE_PATH), WORKSPACE_PATH);
101	    if (notice !== undefined) {
102	      console.error(`[workspace_guard] the workspace is over its limit; telling the agent`);
103	      console.log(JSON.stringify({ notice }));
104	    }
105	  } catch (error) {
106	    // Never the agent's problem. The run log is where this belongs.
107	    console.error(`[workspace_guard] could not measure ${WORKSPACE_PATH}: ${(error as Error).message}`);
108	  }
109	}
110	
111	if (import.meta.main) await main();
